#include <bits/stdc++.h>
using namespace std;

int main() {
 int n;
 if (scanf("%d", &n) != 1) return 0;
 long long total = 0, shares = 0;
 for (int i = 0; i < n; i++) {
 long long q, c;
 scanf("%lld %lld", &q, &c);
 total += c * q;
 shares += q;
 }
 long long num = total * 100; // vwap*10000 = num / den
 long long den = shares;
 long long q4 = num / den, rem = num % den;
 if (2 * rem > den || (2 * rem == den && q4 % 2 != 0)) q4++; // round half to even
 printf("%lld.%04lld\n", q4 / 10000, q4 % 10000);
 return 0;
}
